use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == 1
{
    let n: usize = a.len();
    let mut result: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            i <= n,
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == 1,
        decreases n - i,
    {
        result.push(1);
        i = i + 1;
    }

    result
}

} // verus!

